/**
 * Verifies an Apple App Attest attestation object, following the steps in
 * Apple's "Validating apps that connect to your server":
 * https://developer.apple.com/documentation/devicecheck/validating-apps-that-connect-to-your-server
 *
 * A passing attestation means Apple vouches that `keyId` names a key held in
 * the Secure Enclave of a genuine Apple device, generated by the app `appId`,
 * and that the app committed to `clientDataHash` when it was attested.
 */
import { x509 } from "./x509";
import { decode } from "cbor-x";
import { bytesEqual, concat, sha256 } from "./bytes";


/** Apple's nonce extension on the credential certificate. */
const NONCE_EXTENSION_OID = "1.2.840.113635.100.8.2";
const AAGUID = {
  production: new TextEncoder().encode("appattest\0\0\0\0\0\0\0"),
  development: new TextEncoder().encode("appattestdevelop"),
} as const;

export type AttestEnvironment = keyof typeof AAGUID;

export class AttestationError extends Error {
  constructor(
    readonly code:
      | "malformed"
      | "untrusted_chain"
      | "nonce_mismatch"
      | "key_id_mismatch"
      | "app_id_mismatch"
      | "counter_not_zero"
      | "environment_not_allowed",
    message: string
  ) {
    super(message);
    this.name = "AttestationError";
  }
}

export interface VerifyAttestationInput {
  attestation: Uint8Array;
  /** SHA-256 of the attested public key, as returned by `generateKey()` (base64-decoded). */
  keyId: Uint8Array;
  clientDataHash: Uint8Array;
  /** `<TeamID>.<BundleID>` */
  appId: string;
  allowedEnvironments: AttestEnvironment[];
  rootCertificatePem: string;
  now?: Date;
}

export interface VerifiedAttestation {
  /** The App Attest key (uncompressed P-256 point), needed later to verify assertions. */
  publicKey: Uint8Array;
  receipt: Uint8Array;
  environment: AttestEnvironment;
}

interface AttestationObject {
  fmt: string;
  attStmt: { x5c: Uint8Array[]; receipt: Uint8Array };
  authData: Uint8Array;
}

export async function verifyAttestation(input: VerifyAttestationInput): Promise<VerifiedAttestation> {
  const now = input.now ?? new Date();
  const att = decodeAttestation(input.attestation);
  const [leafDer, intermediateDer] = att.attStmt.x5c;
  const leaf = new x509.X509Certificate(leafDer!);
  const intermediate = new x509.X509Certificate(intermediateDer!);
  const root = new x509.X509Certificate(input.rootCertificatePem);

  // 1. The certificates chain to Apple's App Attestation root, and are valid now.
  const intermediateOk = await intermediate.verify({ publicKey: root.publicKey, date: now });
  const leafOk = intermediateOk && (await leaf.verify({ publicKey: intermediate.publicKey, date: now }));
  if (!leafOk) throw new AttestationError("untrusted_chain", "Certificate chain does not verify to the Apple root");

  // 2–4. nonce = SHA256(authData ‖ clientDataHash) must equal the certificate's nonce extension.
  const expectedNonce = sha256(concat(att.authData, input.clientDataHash));
  const extension = leaf.getExtension(NONCE_EXTENSION_OID);
  if (!extension) throw new AttestationError("malformed", "Credential certificate has no nonce extension");
  if (!bytesEqual(parseNonceExtension(new Uint8Array(extension.value)), expectedNonce)) {
    throw new AttestationError("nonce_mismatch", "Nonce does not match authData and clientDataHash");
  }

  // 5. The key identifier is the SHA-256 of the credential certificate's public key.
  const publicKey = await rawP256PublicKey(leaf);
  if (!bytesEqual(sha256(publicKey), input.keyId)) {
    throw new AttestationError("key_id_mismatch", "keyId is not the hash of the attested public key");
  }

  const auth = parseAuthenticatorData(att.authData);

  // 6. The RP ID hash is the SHA-256 of our App ID.
  if (!bytesEqual(auth.rpIdHash, sha256(new TextEncoder().encode(input.appId)))) {
    throw new AttestationError("app_id_mismatch", "Attestation is for a different app");
  }

  // 7. A fresh attestation has a counter of zero.
  if (auth.counter !== 0) throw new AttestationError("counter_not_zero", "Attestation counter is not zero");

  // 8. The AAGUID says which App Attest environment produced it.
  const environment = (Object.keys(AAGUID) as AttestEnvironment[]).find((env) =>
    bytesEqual(auth.aaguid, AAGUID[env])
  );
  if (!environment || !input.allowedEnvironments.includes(environment)) {
    throw new AttestationError("environment_not_allowed", `App Attest environment not allowed: ${environment ?? "unknown"}`);
  }

  // 9. The credential ID is the key identifier.
  if (!bytesEqual(auth.credentialId, input.keyId)) {
    throw new AttestationError("key_id_mismatch", "Credential ID does not match keyId");
  }

  return { publicKey, receipt: att.attStmt.receipt, environment };
}

function decodeAttestation(bytes: Uint8Array): AttestationObject {
  let obj: unknown;
  try {
    obj = decode(bytes);
  } catch {
    throw new AttestationError("malformed", "Attestation is not valid CBOR");
  }
  const att = obj as Partial<AttestationObject> | null;
  if (
    att?.fmt !== "apple-appattest" ||
    !(att.authData instanceof Uint8Array) ||
    !Array.isArray(att.attStmt?.x5c) ||
    att.attStmt.x5c.length < 2 ||
    !att.attStmt.x5c.every((c) => c instanceof Uint8Array) ||
    !(att.attStmt.receipt instanceof Uint8Array)
  ) {
    throw new AttestationError("malformed", "Not an apple-appattest attestation object");
  }
  return att as AttestationObject;
}

/**
 * The extension value is DER: SEQUENCE { [1] EXPLICIT OCTET STRING (32 bytes) }.
 * Parsed strictly rather than taking "the last 32 bytes".
 */
function parseNonceExtension(der: Uint8Array): Uint8Array {
  const fail = () => {
    throw new AttestationError("malformed", "Unexpected nonce extension encoding");
  };
  const expectTag = (offset: number, tag: number, length: number) => {
    if (der[offset] !== tag || der[offset + 1] !== length) fail();
  };
  if (der.length !== 38) fail();
  expectTag(0, 0x30, 36); // SEQUENCE
  expectTag(2, 0xa1, 34); // [1] EXPLICIT
  expectTag(4, 0x04, 32); // OCTET STRING
  return der.slice(6, 38);
}

async function rawP256PublicKey(cert: x509.X509Certificate): Promise<Uint8Array> {
  const key = await crypto.subtle.importKey(
    "spki",
    cert.publicKey.rawData,
    { name: "ECDSA", namedCurve: "P-256" },
    true,
    ["verify"]
  );
  return new Uint8Array(await crypto.subtle.exportKey("raw", key));
}

function parseAuthenticatorData(authData: Uint8Array) {
  // rpIdHash (32) | flags (1) | counter (4) | aaguid (16) | credIdLen (2) | credId | publicKey (COSE)
  if (authData.length < 55) throw new AttestationError("malformed", "authData too short");
  const view = new DataView(authData.buffer, authData.byteOffset, authData.byteLength);
  const credentialIdLength = view.getUint16(53);
  if (authData.length < 55 + credentialIdLength) throw new AttestationError("malformed", "authData truncated");
  return {
    rpIdHash: authData.slice(0, 32),
    counter: view.getUint32(33),
    aaguid: authData.slice(37, 53),
    credentialId: authData.slice(55, 55 + credentialIdLength),
  };
}
